/// Reproduce C++ `std::cout << v` for a `double` under the default C locale and
/// default stream state (fmtflags floatfield unset == `defaultfloat`,
/// `precision() == 6`, no `showpoint`, no `showpos`).
///
/// This is exactly `printf("%g", v)` with precision 6:
///   - let X = decimal exponent of v after rounding to 6 significant digits;
///   - if -4 <= X < 6  -> fixed notation with precision (6 - 1 - X);
///   - else            -> scientific notation with precision (6 - 1), exponent
///                        always signed and zero-padded to >= 2 digits;
///   - in both cases trailing zeros in the fraction are removed, and the '.'
///     is removed if the fraction becomes empty.
pub fn format_double_ostream(v: f64) -> String {
    // std::cout.precision() default; %g treats precision 0 as 1 (not reachable here).
    const PREC: usize = 6;

    if v.is_nan() {
        // glibc/libstdc++ print the NaN sign bit; Rust's Display does not.
        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }

    // Round to PREC significant digits. Rust's LowerExp with an explicit
    // precision yields "<sign>d.ddddde<exp>" where <exp> has no '+' and no
    // zero padding (e.g. "1.23457e6", "1.00000e-310", "0.00000e0").
    // Rust's exact-mode rounding is round-half-to-even on the exact binary
    // value, which is what glibc printf does under the default FP rounding mode.
    let sci = format!("{:.*e}", PREC - 1, v);
    let (mantissa, exp_str) = sci.split_once('e').expect("LowerExp always emits 'e'");
    let x: i32 = exp_str.parse().expect("LowerExp exponent is a valid i32");

    if x < -4 || x >= PREC as i32 {
        // Scientific style.
        let m = trim_fraction(mantissa);
        let sign = if x < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, x.unsigned_abs())
    } else {
        // Fixed style. Rounds to the same decimal place 10^(x - PREC + 1) that
        // produced `x` above, so there is no double-rounding hazard.
        let frac_digits = (PREC as i32 - 1 - x) as usize; // 0..=9
        let s = format!("{:.*}", frac_digits, v);
        trim_fraction(&s).to_string()
    }
}

/// Strip trailing zeros of a fractional part, then a bare trailing '.'.
/// Must be a no-op when there is no '.' at all ("100000" must not become "1").
fn trim_fraction(s: &str) -> &str {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.strip_suffix('.').unwrap_or(t)
    } else {
        s
    }
}

fn main() {
    let cases: &[(f64, &str)] = &[
        (6250.0, "6250"), (0.0, "0"), (-0.0, "-0"), (1.0 / 3.0, "0.333333"),
        (1e-5, "1e-05"), (1e-4, "0.0001"), (123456.0, "123456"), (1234567.0, "1.23457e+06"),
        (0.0001234567, "0.000123457"), (1e20, "1e+20"), (-2.5, "-2.5"),
        (f64::INFINITY, "inf"), (f64::NEG_INFINITY, "-inf"), (f64::NAN, "nan"),
        (-f64::NAN, "-nan"), (100.0, "100"), (1e6, "1e+06"), (999999.0, "999999"),
        (999999.5, "1e+06"), (0.1, "0.1"), (12345.6789, "12345.7"),
        (3.14159265358979, "3.14159"), (2.0 / 3.0, "0.666667"), (1e15, "1e+15"),
        (1e-100, "1e-100"), (5e-324, "4.94066e-324"), (1e250, "1e+250"),
        (1234565.0, "1.23456e+06"), (1234575.0, "1.23458e+06"), (-1234567.0, "-1.23457e+06"),
        (1e-7, "1e-07"), (1024.0, "1024"), (1e-3, "0.001"), (1.0, "1"), (2.5e-5, "2.5e-05"),
    ];
    let mut bad = 0;
    for (v, want) in cases {
        let got = format_double_ostream(*v);
        if got != *want { println!("FAIL {:?} want={} got={}", v, want, got); bad += 1; }
    }
    println!("cases={} failures={}", cases.len(), bad);
}
